			//Paso 5.1: Imprimir el nombre del pais en la fila i
			System.out.printf("%4s", countries[i]);
			//Paso 5.2: Inicializar la variable que necesitamos para almacenar el total de la fila i
			int rowTotal = 0;
			//Paso 5.3: Iterar a traves de las columnas de la matriz de conteo de medallas
			for (int j = 0; j < medalCounts[0].length; j++) {
				//Paso 5.3.1: Imprimir el numero de medallas en la fila i y columna j de la matriz
				System.out.printf("%3d", medalCounts[i][j]);
				//Paso 5.3.2: Actualizar el total de la fila i
				rowTotal = rowTotal + medalCounts[i][j];
		        //Paso 5.3.3: Actualizar el total de la columna j
				columnTotals[j] += medalCounts[i][j];
			}
			//Paso 5.4: Imprimir el total de la fila i en la tabla de salida
			System.out.printf("%3d\n", rowTotal);        
		}
		//Paso 6: Imprimir los totales de columnas
		System.out.printf("%4s", "Total");
		for (int x : columnTotals) {
			System.out.printf("%3d", x);
		}
	}
}

